import manifest from '@site/static/manifests/skills.json';

// The catalogue: every skill in static/manifests/skills.json (generated by
// misc/update-pages.sh), joined with the short, hand-written lines a visitor
// needs to choose a skill: which job it does, what it is for, what it is not
// for and what you get. A skill missing from LINES still shows, with the
// first sentence of its description, so a new skill never disappears.

export type Platform = 'eks' | 'ecs' | 'general';

export type JobId = 'knowledge' | 'design' | 'build' | 'assess' | 'migrate' | 'secure' | 'extend';

export type Skill = {
  name: string;
  description: string;
  summary?: string;
  path: string;
  group: Platform;
};

export type CatalogSkill = Skill & {
  job: JobId;
  use: string;
  notFor?: string;
  output?: string;
};

// The site's interim grouping (Knowledge Skills, then Solution Skills by day,
// then tooling), until the v2 skill classes land. stage names the parent a
// Day 2 group sits under, for labels such as the one on a skill page.
