function firstSentence(text: string): string {
  const match = text.trim().match(/^(.+?[.!?])(\s|$)/);
  return match ? match[1] : text.trim();
}

export const SKILLS: CatalogSkill[] = (manifest as Skill[]).map((skill) => {
  const lines = LINES[skill.name];
  return {
    ...skill,
    job: lines?.job ?? 'extend',
    use: lines?.use ?? skill.summary ?? firstSentence(skill.description),
    notFor: lines?.notFor,
    output: lines?.output,
  };
});

// The skill's page, with the trailing slash its generated index page uses.
export function skillHref(skill: Skill): string {
  return `${skill.path.replace(/\/$/, '')}/`;
}

export const skillCount = SKILLS.length;

export function platformCounts(list: CatalogSkill[]): Record<Platform, number> {
  const counts: Record<Platform, number> = {eks: 0, ecs: 0, general: 0};
  for (const s of list) counts[s.group] += 1;
  return counts;
}
